// Streaming terrain meshes sample the exact height model used by ground physics. Tiles are
// generated by terrain-build.js, in a Web Worker when available so streaming never stalls
// the flight; meshes are assembled here from the returned typed arrays.
// Vertex colours give the broad land cover (beaches, meadows, forests, rock, snow, towns and
// the sea bed seen through the water); a shader adds field patchworks, hedgerows, forest canopy
// and multi-scale detail that stays sharp from the cockpit up to cruise altitude.
import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { getTerrain } from '../world/terrain-height.js';
import { applyAtmosphere } from './atmosphere.js';
import { buildTileData, TILE } from './terrain-build.js';
import { getDetailTexture, getMaterialTexture } from './textures.js';
import { sceneryUniforms } from './materials.js';

export function getTerrainProfile(quality = 'medium') {
  const level = ['low', 'medium', 'high'].includes(quality) ? quality : 'medium';
  return {
    quality: level,
    radius: level === 'low' ? 3 : level === 'high' ? 6 : 5,
    segments: level === 'low' ? [24, 16, 8] : [64, 32, 8],
    treeSamples: level === 'low' ? 40 : level === 'high' ? 520 : 260,
  };
}

const TERRAIN_VERTEX_PARS = /* glsl */`
attribute vec4 aTerrain;
attribute vec3 aCover;
varying vec4 vTerrain;
varying vec3 vCover;
varying vec3 vTerrainPos;
varying vec3 vTerrainNormal;
`;

// Material textures blended by land cover (generated by tools/make-textures.py).
const TERRAIN_TEXTURES = ['grass', 'forest', 'rock', 'sand', 'snow', 'soil', 'rock_normal', 'ground_normal'];

const TERRAIN_FRAGMENT_PARS = /* glsl */`
uniform sampler2D uDetail;
uniform float uNight;
uniform sampler2D tGrass;
uniform sampler2D tForest;
uniform sampler2D tRock;
uniform sampler2D tSand;
uniform sampler2D tSnow;
uniform sampler2D tSoil;
uniform sampler2D tRockNormal;
uniform sampler2D tGroundNormal;
varying vec4 vTerrain;
varying vec3 vCover;
varying vec3 vTerrainPos;
varying vec3 vTerrainNormal;
float terrainFar;
// Texture detail relative to its own mean colour: adds grain while keeping the land-cover tint.
// The second scale is rotated and the fine one fades with distance, which hides the tiling.
vec3 terrainTex(sampler2D t, vec2 a, vec2 b) {
  vec3 mean = max(textureLod(t, vec2(0.5), 12.0).rgb, vec3(0.03));
  vec2 rb = vec2(0.8 * b.x - 0.6 * b.y, 0.6 * b.x + 0.8 * b.y);
  #ifdef TERRAIN_HQ
    float wa = mix(0.62, 0.1, terrainFar);
    return (texture2D(t, a).rgb * wa + texture2D(t, rb).rgb * (1.0 - wa)) / mean;
  #else
    return texture2D(t, rb).rgb / mean;
  #endif
}
// Rock uses triplanar projection so cliffs are not stretched.
vec3 terrainRock(vec3 p, vec3 n) {
  vec3 mean = max(textureLod(tRock, vec2(0.5), 12.0).rgb, vec3(0.03));
  #ifdef TERRAIN_HQ
    vec3 w = pow(abs(n), vec3(4.0));
    w /= w.x + w.y + w.z;
    vec3 c = texture2D(tRock, p.zy / 19.0).rgb * w.x + texture2D(tRock, vec2(p.x, -p.z) / 19.0).rgb * w.y + texture2D(tRock, p.xy / 19.0).rgb * w.z;
    c = c * 0.65 + texture2D(tRock, vec2(p.x, -p.z) / 97.0).rgb * 0.35;
  #else
    vec3 c = texture2D(tRock, vec2(p.x, -p.z) / 19.0).rgb;
  #endif
  return c / mean;
}
vec3 terrainLinear(vec3 c) { return pow(c, vec3(2.2)); }
float terrainHash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
vec3 fieldColor(float h) {
  if (h < 0.17) return vec3(0.80, 0.70, 0.41);  // ripe wheat
  if (h < 0.33) return vec3(0.49, 0.60, 0.29);  // young crop
  if (h < 0.46) return vec3(0.37, 0.48, 0.24);  // lucerne
  if (h < 0.60) return vec3(0.55, 0.43, 0.31);  // ploughed soil
  if (h < 0.71) return vec3(0.67, 0.62, 0.44);  // stubble
  if (h < 0.85) return vec3(0.47, 0.53, 0.35);  // olive grove
  if (h < 0.94) return vec3(0.60, 0.64, 0.38);  // meadow
  return vec3(0.82, 0.71, 0.25);                // sunflowers
}
`;

const TERRAIN_FRAGMENT = /* glsl */`
{
  vec2 wp = vec2(vTerrainPos.x, -vTerrainPos.z);
  vec4 d1 = texture2D(uDetail, wp * (1.0 / 53.0));
  vec4 d2 = texture2D(uDetail, wp * (1.0 / 397.0));
  vec4 d3 = texture2D(uDetail, wp * (1.0 / 2900.0));
  vec3 base = diffuseColor.rgb;
  base *= 0.84 + 0.32 * d3.a;
  base *= 0.9 + 0.2 * d2.g;
  float forest = vTerrain.y;
  base *= mix(1.0, 0.55 + 0.85 * d2.b, forest);
  float fw = vTerrain.x;
  vec2 q = wp;
  if (fw > 0.01) {
    float ca = cos(vTerrain.z), sa = sin(vTerrain.z);
    q = vec2(ca * wp.x - sa * wp.y, sa * wp.x + ca * wp.y) + (d3.rg - 0.5) * 140.0;
    vec2 cs = vec2(380.0, 260.0);
    vec2 c = q / cs;
    vec2 id = floor(c);
    vec2 f = fract(c);
    float h = terrainHash(id);
    if (h > 0.55) {
      float k = floor(f.x * 3.0);
      id += vec2(k * 0.31 + 7.0, 3.0);
      f.x = fract(f.x * 3.0);
      cs.x /= 3.0;
      h = terrainHash(id);
    }
    vec3 fc = terrainLinear(fieldColor(h));
    float rows = texture2D(uDetail, vec2(q.x * 0.45, q.y * 0.015)).r;
    fc *= 0.86 + 0.28 * rows;
    vec2 edge = min(f, 1.0 - f) * cs;
    float e = min(edge.x, edge.y);
    float px = max(length(fwidth(q)), 0.001);
    float hedge = 1.0 - smoothstep(1.8, 1.8 + px * 1.5, e);
    fc = mix(fc, terrainLinear(vec3(0.25, 0.31, 0.17)), hedge * (h > 0.3 ? 0.8 : 0.35));
    float detail = 1.0 - smoothstep(30.0, 140.0, px);
    fc = mix(terrainLinear(vec3(0.58, 0.58, 0.37)), fc, detail);
    base = mix(base, fc * (0.9 + 0.2 * d2.g), fw);
  }
  // Close range: material textures and relief normals by land cover.
  float camDist = length(vTerrainPos - cameraPosition);
  vec3 tn = normalize(vTerrainNormal);
  float wRock = vCover.x, wSnow = vCover.y, wSand = vCover.z;
  vec2 relief = (texture2D(tRockNormal, wp / 610.0).xy * 2.0 - 1.0) * (0.28 * wRock + 0.08);
  if (camDist < 4500.0) {
    terrainFar = smoothstep(120.0, 800.0, camDist);
    // Soft covers fade out early (their tiling would show); rock keeps its texture further.
    float nearFade = 1.0 - smoothstep(450.0, 1500.0, camDist);
    float rockFade = 1.0 - smoothstep(1800.0, 4500.0, camDist);
    float wField = fw * (1.0 - wRock);
    float wGrass = max(0.0, 1.0 - wRock - wSnow - wSand - forest - wField);
    vec3 one = vec3(1.0);
    // Every cover keeps its full weight; a faded or skipped texture contributes neutral 1.
    vec3 detail = one * (wGrass + forest + wField + wSand + wSnow + wRock);
    if (nearFade > 0.0) {
      if (wGrass > 0.02) detail += wGrass * nearFade * (terrainTex(tGrass, wp / 5.3, wp / 61.0) - one);
      if (forest > 0.02) detail += forest * nearFade * (terrainTex(tForest, wp / 41.0, wp / 157.0) - one);
      if (wField > 0.02) {
        // Furrows follow the field grid; a single scale avoids crossed rows and moiré.
        vec3 soil = texture2D(tSoil, q / 11.0).rgb / max(textureLod(tSoil, vec2(0.5), 12.0).rgb, vec3(0.03));
        detail += wField * nearFade * (soil - one);
      }
      if (wSand > 0.02) detail += wSand * nearFade * (terrainTex(tSand, wp / 7.0, wp / 43.0) - one);
      if (wSnow > 0.02) detail += wSnow * nearFade * (terrainTex(tSnow, wp / 23.0, wp / 101.0) - one);
    }
    if (wRock > 0.02) detail += wRock * rockFade * (terrainRock(vTerrainPos, tn) - one);
    detail /= max(wGrass + forest + wField + wSand + wSnow + wRock, 0.001);
    base *= detail;
    #ifdef TERRAIN_HQ
      vec2 nr = (texture2D(tRockNormal, wp / 27.0).xy * 2.0 - 1.0) * wRock * 0.5 * rockFade;
      vec2 ng = (texture2D(tGroundNormal, wp / 4.5).xy * 2.0 - 1.0) * (1.0 - wRock) * 0.55 * (1.0 - smoothstep(150.0, 900.0, camDist));
      relief += nr + ng;
    #endif
  }
  terrainNormalWorld = normalize(tn + vec3(relief.x, 0.0, -relief.y));
  base *= 0.9 + 0.2 * d1.r;
  diffuseColor.rgb = base;
  // Towns glow orange at night: street lighting scattered on the ground.
  terrainCityGlow = vec3(1.0, 0.55, 0.22) * vTerrain.w * uNight * (0.25 + 0.75 * smoothstep(0.35, 0.8, d1.b + d2.g * 0.5)) * 0.16;
}
`;

function createTerrainMaterial() {
  const material = new THREE.MeshLambertMaterial({ vertexColors: true });
  const detail = getDetailTexture();
  return applyAtmosphere(material, 'terrain', (shader) => {
    shader.uniforms.uDetail = { value: detail };
    shader.uniforms.uNight = sceneryUniforms.uNight;
    for (const name of TERRAIN_TEXTURES) {
      shader.uniforms[`t${name.replace(/(^|_)(\w)/g, (_, __, c) => c.toUpperCase())}`] = getMaterialTexture(name);
    }
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', `#include <common>\n${TERRAIN_VERTEX_PARS}`)
      .replace('#include <project_vertex>', `#include <project_vertex>
        vTerrain = aTerrain;
        vCover = aCover;
        vTerrainNormal = objectNormal;
        vTerrainPos = (modelMatrix * vec4(transformed, 1.0)).xyz;`);
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', `#include <common>\n${TERRAIN_FRAGMENT_PARS}`)
      .replace('#include <color_fragment>', `#include <color_fragment>
        vec3 terrainCityGlow = vec3(0.0);
        vec3 terrainNormalWorld = vec3(0.0, 1.0, 0.0);
        ${TERRAIN_FRAGMENT}`)
      .replace('#include <normal_fragment_maps>', '#include <normal_fragment_maps>\nnormal = normalize((viewMatrix * vec4(terrainNormalWorld, 0.0)).xyz);')
      .replace('#include <emissivemap_fragment>', '#include <emissivemap_fragment>\ntotalEmissiveRadiance += terrainCityGlow;');
  });
}

/** Unit-height tree with its base at the origin; vertex colours: trunk brown, crown green. */
function treeGeometry(kind) {
  const parts = [];
  const paint = (geometry, color, shadeBottom = 0.72) => {
    const g = geometry.index ? geometry.toNonIndexed() : geometry;
    g.deleteAttribute('uv');
    const p = g.attributes.position;
    g.computeBoundingBox();
    const { min, max } = g.boundingBox;
    const colors = new Float32Array(p.count * 3);
    for (let i = 0; i < p.count; i++) {
      // Darker towards the bottom of each crown: cheap ambient occlusion.
      const k = shadeBottom + (1 - shadeBottom) * (p.getY(i) - min.y) / Math.max(1e-6, max.y - min.y);
      colors.set([color.r * k, color.g * k, color.b * k], i * 3);
    }
    g.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    parts.push(g);
  };
  const trunk = new THREE.Color(0x5a4632);
  const leaves = new THREE.Color(0xffffff);
  if (kind === 'conifer') {
    paint(new THREE.CylinderGeometry(0.035, 0.05, 0.22, 4, 1, true).translate(0, 0.11, 0), trunk, 1);
    paint(new THREE.ConeGeometry(0.36, 0.55, 6, 1, true).translate(0, 0.42, 0), leaves, 0.55);
    paint(new THREE.ConeGeometry(0.26, 0.45, 6, 1, true).translate(0, 0.76, 0), leaves, 0.65);
  } else {
    paint(new THREE.CylinderGeometry(0.04, 0.06, 0.42, 4, 1, true).translate(0, 0.21, 0), trunk, 1);
    paint(new THREE.IcosahedronGeometry(0.42, 0).scale(1, 0.82, 1).translate(0, 0.66, 0), leaves, 0.5);
  }
  const merged = mergeGeometries(parts, false);
  for (const part of parts) part.dispose();
  return merged;
}

export class TerrainTiles {
  constructor(scene, quality = 'medium') {
    this.scene = scene;
    this.terrain = getTerrain();
    this.tiles = new Map();
    this.queue = [];
    this.inFlight = new Map();
    this.inFlightKeys = new Set();
    this.desired = new Map();
    this.jobId = 0;
    this.worker = null;
    this.workerFailed = false;
    this.material = createTerrainMaterial();
    this.treeMaterial = applyAtmosphere(new THREE.MeshLambertMaterial({ vertexColors: true }), 'trees');
    this.treeGeometry = treeGeometry('conifer');
    this.broadleafGeometry = treeGeometry('broadleaf');
    this.receiveShadow = false;
    this.setQuality(quality);
  }

  setQuality(quality) {
    const profile = getTerrainProfile(quality);
    if (profile.quality === this.quality) return;
    this.profile = profile;
    this.quality = profile.quality;
    this.radius = profile.radius;
    this.center = '';
    // Medium/high: two texture scales, triplanar rock and close-range relief normals.
    this.material.defines = profile.quality === 'low' ? {} : { TERRAIN_HQ: '' };
    this.material.needsUpdate = true;
  }

  /** Distance (m) at which streamed terrain ends in every direction. */
  get visibleRange() {
    return this.radius * TILE;
  }

  setShadows(enabled) {
    this.receiveShadow = enabled;
    for (const tile of this.tiles.values()) tile.mesh.receiveShadow = enabled;
  }

  plan(n, e) {
    const ni = Math.floor(n / TILE), ei = Math.floor(e / TILE);
    const center = `${ni}:${ei}:${this.quality}`;
    if (this.center === center) return;
    this.center = center;
    const wanted = new Set();
    const queue = [];
    this.desired.clear();
    for (let dn = -this.radius; dn <= this.radius; dn++) {
      for (let de = -this.radius; de <= this.radius; de++) {
        const distance = Math.max(Math.abs(dn), Math.abs(de));
        const segments = this.profile.segments[distance <= 1 ? 0 : distance <= 2 ? 1 : 2];
        const nn = ni + dn, ee = ei + de, key = `${nn}:${ee}`;
        wanted.add(key);
        this.desired.set(key, segments);
        const old = this.tiles.get(key);
        const job = { nn, ee, key, segments, quality: this.quality, priority: dn * dn + de * de };
        if ((!old || old.segments !== segments || old.quality !== this.quality) && !this.inFlightKeys.has(this._signature(job))) queue.push(job);
      }
    }
    for (const [key, tile] of this.tiles) {
      if (!wanted.has(key)) this.remove(key, tile);
    }
    this.queue = queue.sort((a, b) => a.priority - b.priority);
  }

  remove(key, tile) {
    this.scene.remove(tile.group);
    tile.mesh.geometry.dispose();
    // Per-tile instance attributes have their own GPU buffers. Shared geometry and
    // materials stay alive until the entire terrain streamer is disposed.
    tile.group.traverse((object) => { if (object.isInstancedMesh) object.dispose(); });
    this.tiles.delete(key);
  }

  /** Tiles waiting to be generated or currently being generated. */
  get busy() {
    return this.queue.length + this.inFlight.size;
  }

  _jobData(job) {
    const trees = job.segments >= (job.quality === 'low' ? 24 : 32);
    return { nn: job.nn, ee: job.ee, segments: job.segments, treeSamples: trees ? this.profile.treeSamples : 0, treeDensity: job.segments >= 64 ? 3 : 1 };
  }

  /** Builds the next queued tile on this thread (fallback, tests and loading screens). */
  buildOne() {
    const job = this.queue.shift();
    if (!job) return false;
    this._install(job, buildTileData(this._jobData(job)));
    return true;
  }

  _worker() {
    if (this.workerFailed || typeof Worker === 'undefined') return null;
    if (!this.worker) {
      try {
        this.worker = new Worker(new URL('./terrain-worker.js', import.meta.url), { type: 'module' });
      } catch {
        this.workerFailed = true;
        return null;
      }
      this.worker.onmessage = (event) => this._receive(event.data);
      // A worker that cannot start (old browser, blocked origin) hands its jobs back.
      this.worker.onerror = (event) => { event.preventDefault?.(); this._abandonWorker(); };
      this.worker.onmessageerror = () => this._abandonWorker();
    }
    return this.worker;
  }

  _abandonWorker() {
    this.workerFailed = true;
    this.worker?.terminate();
    this.worker = null;
    const pending = [...this.inFlight.values()];
    this.inFlight.clear();
    this.inFlightKeys.clear();
    this.queue.unshift(...pending.sort((a, b) => a.priority - b.priority));
  }

  /**
   * Called every frame: keeps up to `parallel` tiles in the worker; without a worker it
   * builds one tile synchronously, as before.
   */
  stream(parallel = 2) {
    const worker = this._worker();
    if (!worker) {
      if (this.queue.length) this.buildOne();
      return;
    }
    while (this.inFlight.size < parallel && this.queue.length) {
      const job = this.queue.shift();
      job.id = ++this.jobId;
      this.inFlight.set(job.id, job);
      this.inFlightKeys.add(this._signature(job));
      worker.postMessage({ id: job.id, ...this._jobData(job) });
    }
  }

  _signature(job) {
    return `${job.key}:${job.segments}:${job.quality}`;
  }

  _receive({ id, data, error }) {
    const job = this.inFlight.get(id);
    if (!job) return;
    this.inFlight.delete(id);
    this.inFlightKeys.delete(this._signature(job));
    if (error) {
      // Rebuild on this thread rather than leaving a hole in the terrain.
      this.queue.unshift(job);
      return;
    }
    // The aircraft may have moved on, or the quality changed, while the tile was built.
    if (this.desired.get(job.key) !== job.segments || job.quality !== this.quality) return;
    this._install(job, data);
  }

  _install(job, data) {
    const { nn, ee, key, segments } = job;
    const n0 = nn * TILE, e0 = ee * TILE;
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.BufferAttribute(data.positions, 3));
    geometry.setAttribute('normal', new THREE.BufferAttribute(data.normals, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(data.colors, 3));
    geometry.setAttribute('aTerrain', new THREE.BufferAttribute(data.terrain, 4));
    geometry.setAttribute('aCover', new THREE.BufferAttribute(data.cover, 3));
    geometry.setIndex(new THREE.BufferAttribute(data.index, 1));
    geometry.computeBoundingSphere();
    // Vertices are in world coordinates; the mesh cancels the group offset so every tile
    // draws with the same identity model matrix and shared edge vertices rasterise identically.
    const mesh = new THREE.Mesh(geometry, this.material);
    mesh.position.set(-e0, 0, n0);
    mesh.receiveShadow = this.receiveShadow;
    const group = new THREE.Group();
    group.position.set(e0, 0, -n0);
    group.add(mesh);
    if (data.trees) {
      for (const [set, shape] of [[data.trees.conifer, this.treeGeometry], [data.trees.broadleaf, this.broadleafGeometry]]) {
        const count = set.matrices.length / 16;
        if (!count) continue;
        const trees = new THREE.InstancedMesh(shape, this.treeMaterial, count);
        trees.instanceMatrix.array.set(set.matrices);
        trees.instanceColor = new THREE.InstancedBufferAttribute(set.colors, 3);
        trees.computeBoundingSphere();
        group.add(trees);
      }
    }
    const old = this.tiles.get(key);
    if (old) this.remove(key, old);
    this.scene.add(group);
    this.tiles.set(key, { group, mesh, segments, quality: job.quality });
  }

  dispose() {
    this.worker?.terminate();
    this.worker = null;
    this.inFlight.clear();
    this.inFlightKeys.clear();
    for (const [key, tile] of this.tiles) this.remove(key, tile);
    this.material.dispose();
    this.treeGeometry.dispose();
    this.broadleafGeometry.dispose();
    this.treeMaterial.dispose();
  }
}
